record.field:
# Ouvrir le compositeur d'email avec le template pour prévisualisation
if records:
    template = env.ref('lolirine_email_templates.email_template_annonce_portail_subscription', raise_if_not_found=False)
    if template:
        # Ouvrir le wizard de composition d'email
        composer = env['mail.compose.message'].create({
            'composition_mode': 'mass_mail' if len(records) > 1 else 'comment',
            'model': 'sale.order',
            'res_ids': records.ids,
            'template_id': template.id,
        })
        # Charger les valeurs du template
        composer._onchange_template_id_wrapper()

        action = {
            'type': 'ir.actions.act_window',
            'name': 'Envoyer Annonce Portail Client',
            'res_model': 'mail.compose.message',
            'res_id': composer.id,
            'view_mode': 'form',
            'target': 'new',
            'context': {
                'default_composition_mode': 'mass_mail' if len(records) > 1 else 'comment',
                'default_model': 'sale.order',
                'default_res_ids': records.ids,
                'default_template_id': template.id,
                'active_ids': records.ids,
            },
        }
    else:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Erreur',
                'message': 'Template d\'email non trouvé. Veuillez réinstaller le module.',
                'type': 'danger',
                'sticky': True,
            }
        }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Attention',
            'message': 'Veuillez sélectionner au moins un abonnement.',
            'type': 'warning',
            'sticky': False,
        }
    }

# Ouvrir le compositeur d'email avec le template pour prévisualisation
if records:
    # Filtrer les contacts avec email
    valid_records = records.filtered(lambda r: r.email)

    if not valid_records:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Attention',
                'message': 'Aucun contact sélectionné n\'a d\'adresse email.',
                'type': 'warning',
                'sticky': False,
            }
        }
    else:
        template = env.ref('lolirine_email_templates.email_template_annonce_portail_partner', raise_if_not_found=False)
        if template:
            # Ouvrir le wizard de composition d'email
            composer = env['mail.compose.message'].create({
                'composition_mode': 'mass_mail' if len(valid_records) > 1 else 'comment',
                'model': 'res.partner',
                'res_ids': valid_records.ids,
                'template_id': template.id,
            })
            # Charger les valeurs du template
            composer._onchange_template_id_wrapper()

            action = {
                'type': 'ir.actions.act_window',
                'name': 'Envoyer Annonce Portail Client',
                'res_model': 'mail.compose.message',
                'res_id': composer.id,
                'view_mode': 'form',
                'target': 'new',
                'context': {
                    'default_composition_mode': 'mass_mail' if len(valid_records) > 1 else 'comment',
                    'default_model': 'res.partner',
                    'default_res_ids': valid_records.ids,
                    'default_template_id': template.id,
                    'active_ids': valid_records.ids,
                },
            }

            # Notification si certains contacts ont été ignorés
            skipped = len(records) - len(valid_records)
            if skipped > 0:
                action = [
                    {
                        'type': 'ir.actions.client',
                        'tag': 'display_notification',
                        'params': {
                            'title': 'Information',
                            'message': f'{skipped} contact(s) ignoré(s) car sans adresse email.',
                            'type': 'info',
                            'sticky': False,
                        }
                    },
                    action
                ]
        else:
            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'Erreur',
                    'message': 'Template d\'email non trouvé. Veuillez réinstaller le module.',
                    'type': 'danger',
                    'sticky': True,
                }
            }
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Attention',
            'message': 'Veuillez sélectionner au moins un contact.',
            'type': 'warning',
            'sticky': False,
        }
    }
